from abc import ABC, abstractmethod
from typing import List, Dict, Any, Callable

# === PROBLEM 1: Strategy Pattern ===
# Bir e-ticaret sitesi farkli kargo hesaplama yontemlerini desteklemeli.
# Yontemler: standart (agirlik * 5), express (agirlik * 10 + 15), ucretsiz (0, 200TL ustu)
# Yeni kargo yontemi eklemek mevcut kodu degistirmemeli.

class ShippingStrategy(ABC):
    @abstractmethod
    def calculate(self, weight: float, order_total: float) -> float:
        pass

# StandardShipping, ExpressShipping, FreeShipping siniflarini yazin
# ShippingCalculator context sinifini yazin (strategy'yi runtime'da degistirebilmeli)


# === PROBLEM 2: Observer Pattern ===
# Bir stok takip sistemi: Urun stoku degistiginde email servisi,
# SMS servisi ve dashboard log'a bildirim gitmeli.
# Yeni observer eklemek mevcut kodu degistirmemeli.

class Observer(ABC):
    @abstractmethod
    def update(self, product: str, old_stock: int, new_stock: int) -> None:
        pass

# EmailNotifier, SMSNotifier, DashboardLogger observer siniflarini yazin
# StockManager (Subject) sinifini yazin - observer'lari subscribe/unsubscribe edebilmeli


# === PROBLEM 3: Factory Pattern ===
# Farkli veritabani turlerini destekleyen bir bağlantı sistemi.
# Turler: PostgreSQL, MongoDB, Redis
# Her birinin connect(), query(), disconnect() metotlari var.
# Yeni DB turu eklemek icin Factory'ye kayit olmak yeterli olmali.

class DatabaseConnection(ABC):
    @abstractmethod
    def connect(self) -> str:
        pass

    @abstractmethod
    def query(self, sql: str) -> List[Dict]:
        pass

    @abstractmethod
    def disconnect(self) -> str:
        pass

# PostgresConnection, MongoConnection, RedisConnection siniflarini yazin
# DatabaseFactory sinifini yazin - register() ile yeni DB turu kaydedilebilmeli


def test_patterns() -> dict:
    """Tum pattern'leri test et ve sonuclari dondur."""
    pass

