from abc import ABC, abstractmethod
from typing import List, Dict, Any, Type

# Strategy Pattern
class ShippingStrategy(ABC):
    @abstractmethod
    def calculate(self, weight: float, order_total: float) -> float:
        pass

class StandardShipping(ShippingStrategy):
    def calculate(self, weight: float, order_total: float) -> float:
        return weight * 5

class ExpressShipping(ShippingStrategy):
    def calculate(self, weight: float, order_total: float) -> float:
        return weight * 10 + 15

class FreeShipping(ShippingStrategy):
    def calculate(self, weight: float, order_total: float) -> float:
        return 0 if order_total >= 200 else weight * 5

class ShippingCalculator:
    def __init__(self, strategy: ShippingStrategy):
        self._strategy = strategy

    def set_strategy(self, strategy: ShippingStrategy):
        self._strategy = strategy

    def calculate(self, weight: float, order_total: float) -> float:
        return self._strategy.calculate(weight, order_total)

# Observer Pattern
class Observer(ABC):
    @abstractmethod
    def update(self, product: str, old_stock: int, new_stock: int) -> None:
        pass

class EmailNotifier(Observer):
    def __init__(self):
        self.notifications = []
    def update(self, product: str, old_stock: int, new_stock: int) -> None:
        self.notifications.append(f'EMAIL: {product} stok {old_stock}->{new_stock}')

class SMSNotifier(Observer):
    def __init__(self):
        self.notifications = []
    def update(self, product: str, old_stock: int, new_stock: int) -> None:
        self.notifications.append(f'SMS: {product} stok {old_stock}->{new_stock}')

class DashboardLogger(Observer):
    def __init__(self):
        self.logs = []
    def update(self, product: str, old_stock: int, new_stock: int) -> None:
        self.logs.append(f'LOG: {product} stok {old_stock}->{new_stock}')

class StockManager:
    def __init__(self):
        self._observers: List[Observer] = []
        self._stocks: Dict[str, int] = {}

    def subscribe(self, observer: Observer):
        self._observers.append(observer)

    def unsubscribe(self, observer: Observer):
        self._observers.remove(observer)

    def _notify(self, product: str, old_stock: int, new_stock: int):
        for obs in self._observers:
            obs.update(product, old_stock, new_stock)

    def update_stock(self, product: str, new_stock: int):
        old_stock = self._stocks.get(product, 0)
        self._stocks[product] = new_stock
        self._notify(product, old_stock, new_stock)

# Factory Pattern
class DatabaseConnection(ABC):
    @abstractmethod
    def connect(self) -> str: pass
    @abstractmethod
    def query(self, sql: str) -> List[Dict]: pass
    @abstractmethod
    def disconnect(self) -> str: pass

class PostgresConnection(DatabaseConnection):
    def connect(self): return 'Connected to PostgreSQL'
    def query(self, sql): return [{'result': f'PG: {sql}'}]
    def disconnect(self): return 'Disconnected from PostgreSQL'

class MongoConnection(DatabaseConnection):
    def connect(self): return 'Connected to MongoDB'
    def query(self, sql): return [{'result': f'Mongo: {sql}'}]
    def disconnect(self): return 'Disconnected from MongoDB'

class RedisConnection(DatabaseConnection):
    def connect(self): return 'Connected to Redis'
    def query(self, sql): return [{'result': f'Redis: {sql}'}]
    def disconnect(self): return 'Disconnected from Redis'

class DatabaseFactory:
    _registry: Dict[str, Type[DatabaseConnection]] = {}

    @classmethod
    def register(cls, db_type: str, db_class: Type[DatabaseConnection]):
        cls._registry[db_type] = db_class

    @classmethod
    def create(cls, db_type: str) -> DatabaseConnection:
        if db_type not in cls._registry:
            raise ValueError(f'Unknown database type: {db_type}')
        return cls._registry[db_type]()

DatabaseFactory.register('postgres', PostgresConnection)
DatabaseFactory.register('mongo', MongoConnection)
DatabaseFactory.register('redis', RedisConnection)

