}
class ShippingCalculator {
    constructor(strategy) { this.strategy = strategy; }
    setStrategy(s) { this.strategy = s; }
    calculate(w, t) { return this.strategy.calculate(w, t); }
}

// Observer
class EmailNotifier extends Observer {
    constructor() { super(); this.notifications = []; }
    update(product, old, n) { this.notifications.push(`EMAIL: ${product} ${old}->${n}`); }
}
class SMSNotifier extends Observer {
    constructor() { super(); this.notifications = []; }
    update(product, old, n) { this.notifications.push(`SMS: ${product} ${old}->${n}`); }
}
class DashboardLogger extends Observer {
    constructor() { super(); this.logs = []; }
    update(product, old, n) { this.logs.push(`LOG: ${product} ${old}->${n}`); }
}
class StockManager {
    constructor() { this.observers = []; this.stocks = {}; }
    subscribe(o) { this.observers.push(o); }
    unsubscribe(o) { this.observers = this.observers.filter(x => x !== o); }
    updateStock(product, newStock) {
        const old = this.stocks[product] || 0;
        this.stocks[product] = newStock;
        this.observers.forEach(o => o.update(product, old, newStock));
    }
}

// Factory
class PostgresConnection extends DatabaseConnection {
    connect() { return 'Connected to PostgreSQL'; }
    query(sql) { return [{result: `PG: ${sql}`}]; }
    disconnect() { return 'Disconnected from PostgreSQL'; }
}
class MongoConnection extends DatabaseConnection {
    connect() { return 'Connected to MongoDB'; }
    query(sql) { return [{result: `Mongo: ${sql}`}]; }
    disconnect() { return 'Disconnected from MongoDB'; }
}
class RedisConnection extends DatabaseConnection {
    connect() { return 'Connected to Redis'; }
    query(sql) { return [{result: `Redis: ${sql}`}]; }
    disconnect() { return 'Disconnected from Redis'; }
}
class DatabaseFactory {
    static registry = new Map();
    static register(type, cls) { this.registry.set(type, cls); }
    static create(type) {
        if (!this.registry.has(type)) throw new Error(`Unknown: ${type}`);
        return new (this.registry.get(type))();
    }
}
DatabaseFactory.register('postgres', PostgresConnection);
DatabaseFactory.register('mongo', MongoConnection);
DatabaseFactory.register('redis', RedisConnection);
